const body = $input.first().json;
const messages = body.messages;
if (!messages || messages.length === 0) return [];
const msg = messages[0];
const contact = (body.contacts || [])[0] || {};
const waFrom  = msg.from || contact.wa_id || '';
const waName  = (contact.profile || {}).name || waFrom;

// Pass through text, audio, and image — block everything else
if (!['text','audio','image'].includes(msg.type)) return [];

const mediaId = msg.audio?.id || msg.image?.id || '';
const mimeType = msg.audio?.mime_type || msg.image?.mime_type || '';

return [{ json: {
  waFrom,
  waName,
  waMessage: msg.type === 'text' ? ((msg.text || {}).body || '') : '',
  messageType: msg.type,
  mediaId,
  mimeType
}}];

const agentItem = $input.first().json;
const prevData  = $('Parse WhatsApp Message').first().json;
let   aiOutput  = String(agentItem.output || '');

// Strip leaked tool-call markup
aiOutput = aiOutput.replace(/<function=[^>]*>[\s\S]*?<\/function>/gi, '').trim();
aiOutput = aiOutput.replace(/```[\s\S]*?```/g, '').trim();
aiOutput = aiOutput.split('\n').filter(l => !/^\s*\{"input"/.test(l)).join('\n').trim();

// Strip <think>...</think> reasoning blocks (chain-of-thought leak)
aiOutput = aiOutput.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

// Strip ##INTERESTED## signal
const isInterested = aiOutput.includes('##INTERESTED##');
let   cleanMessage = aiOutput;
let   interestedSKUs = [];

// Load static data — stores last shown SKU per customer
const store   = $getWorkflowStaticData('global');
const lastKey = 'lastSKU_' + prevData.waFrom;

if (isInterested) {
  const parts = aiOutput.split('##INTERESTED##');
  cleanMessage = (parts[0] || '').trim();
  const rawSkus = (parts[1] || '').split(',').map(s => s.trim()).filter(Boolean);

  // Fix 2: If AI said LAST_SKU or gave no SKU, use the last shown SKU from static data
  const validSkus = rawSkus.filter(s => s !== 'LAST_SKU' && s !== '' && !/^(SKU|XXXX)$/i.test(s));
  if (validSkus.length > 0) {
    interestedSKUs = [...new Set(validSkus)];
  } else {
    // Fall back to last shown SKU stored in static data
    const fallback = store[lastKey] || '';
    if (fallback) interestedSKUs = [fallback];
  }
}

// Extract SKUs mentioned in AI reply
const skuMatches = [...cleanMessage.matchAll(/\[SKU:\s*([^\]]+)\]/gi)];
const rawMentioned = [...new Set(skuMatches.map(m => m[1].trim()))];

// Save last shown SKU to static data for next turn
if (!isInterested && rawMentioned.length > 0) {
  store[lastKey] = rawMentioned[0]; // save first/primary SKU shown
}

// When interested: clear mentionedSKUs and aiReply to suppress extra messages
const mentionedSKUs = isInterested ? [] : rawMentioned;

// Build clean customer-facing reply
let aiReply = cleanMessage
  .replace(/\[SKU:\s*[^\]]+\]/gi, '')
  .replace(/I[''']ve\s+(just\s+)?(sent|shared|attached|forwarded)\s+(you\s+)?(an?\s+)?(image|photo|picture|pic)[^.!?\n]*/gi, '')
  .replace(/[Hh]ere[''']?s?\s+(an?\s+)?(image|photo|picture|pic)[^.!?\n]*/gi, '')
  .replace(/[Pp]lease\s+(find|see|check)[^.!?\n]*(image|photo|picture|pic)[^.!?\n]*/gi, '')
  .replace(/\s{2,}/g, ' ')
  .replace(/^[\s,\.]+/, '')
  .trim();

// Convert literal \n sequences to real newlines
// AI sometimes outputs \n as escaped text instead of actual newlines

// Blank aiReply for interest — Notify Customer node sends the message instead
if (isInterested) aiReply = '';

// Detect image intent from customer message
const customerMsg   = prevData.waMessage || '';
const wantAllImages = /\b(all|more|another|other|rest|remaining)\b.{0,20}\b(image|photo|pic)/i.test(customerMsg)
                   || /\b(image|photo|pic).{0,20}\b(all|more)/i.test(customerMsg)
                   || /^\s*yes\s*$/i.test(customerMsg);
const wantAnyImage  = /\b(show|see|send|display|view|share)\b.{0,30}\b(image|photo|pic)/i.test(customerMsg)
                   || /\b(image|photo|pic)\b/i.test(customerMsg)
                   || wantAllImages;

return [{
  json: {
    waFrom:        prevData.waFrom,
    waName:        prevData.waName,
    waMessage:     prevData.waMessage,
    aiReply,
    isInterested,
    interestedSKUs,
    mentionedSKUs,
    wantAllImages,
    wantAnyImage
  }
}];

// Fetch full product details for the specific SKUs mentioned by AI
// Uses the cached inventory rows first (fast), falls back to Supabase query
var skuData = $('Extract SKUs from AI Reply').first().json;
var mentionedSKUs = skuData.mentionedSKUs || [];

// Try cache first
var store = $getWorkflowStaticData('global');
var cachedRows = store.inventoryRowsCache || [];

if (cachedRows.length > 0) {
  // Return all cached rows — Resolve SKUs node will filter
  return cachedRows.map(function(r) { return { json: r }; });
}

// Cache miss — fetch from Supabase
var ownerId     = store.ownerId || '';
var SERVICE_KEY = ($env.SUPABASE_SERVICE_KEY || '');
var url = 'https://bigmdvjrvqyqzyrijdum.supabase.co/rest/v1/products'
  + '?owner_id=eq.' + ownerId
  + '&is_current=eq.true&in_stock=eq.true'
  + '&select=sku,name,ai_title,category,gold_carat,diamond_purity,weight,price,stock_qty,ai_occasions,ai_whatsapp_summary,images,primary_image_url';

var resp = await $http.get(url, {
  headers: { 'apikey': SERVICE_KEY, 'Authorization': 'Bearer ' + SERVICE_KEY }
});

var products = resp.data || [];
return products.map(function(p) {
  var images = Array.isArray(p.images) ? p.images : [];
  var row = {
    'SKU': p.sku || '', 'Item Name': p.name || '', 'AI Title': p.ai_title || p.name || '',
    'Category': p.category || '', 'Gold Carat': p.gold_carat || '',
    'Diamond Purity': p.diamond_purity || 'N/A',
    'Weight (g)': p.weight || '', 'Price (INR)': p.price || '',
    'Stock Qty': p.stock_qty || '1', 'Occasions': p.ai_occasions || '',
    'WhatsApp Summary': p.ai_whatsapp_summary || '', 'Status': 'Active',
    'Total Images': String(images.length || 1),
    'Primary Image URL': p.primary_image_url || (images[0] || ''),
  };
  for (var i = 0; i < Math.min(images.length, 5); i++) {
    row['Image ' + (i+1) + ' Direct URL'] = images[i] || '';
  }
  return { json: row };
});

// Convert Cloudinary URL to JPG — WhatsApp only accepts jpeg/png/gif via link
function toWhatsAppUrl(url) {
  if (!url) return '';
  if (url.indexOf('res.cloudinary.com') !== -1) {
    return url.replace(
      /(\/upload\/)(v[0-9]+\/|)/,
      function(m, p1, p2) { return p1 + 'f_jpg,q_auto/' + p2; }
    );
  }
  return url;
}

var skuData       = $('Extract SKUs from AI Reply').first().json;
var inventoryRows = $input.all().map(function(r) { return r.json; })
                       .filter(function(r) { return (r['Status'] || 'Active') !== 'Inactive'; });

var mentionedSKUs  = skuData.mentionedSKUs  || [];
var interestedSKUs = skuData.interestedSKUs || [];
var customerMsg    = skuData.waMessage       || '';

// Detect if customer wants ALL/MORE images of a single item
// (only applies when ONE item is being discussed)
var wantMoreImages = /\b(all|more|another|other|rest|remaining)\b.{0,20}\b(image|photo|pic)/i.test(customerMsg)
                  || /\b(image|photo|pic).{0,20}\b(all|more)/i.test(customerMsg)
                  || /^\s*(yes|yeah|haan|bilkul|zaroor|sure)\s*[.!]*\s*$/i.test(customerMsg);

// When multiple SKUs are present (category listing), NEVER treat as want-more-images
// Each item always gets exactly 1 photo in a multi-item response
var isMultiItem = mentionedSKUs.length > 1;
if (isMultiItem) { wantMoreImages = false; }

var imagesToSend = [];

for (var si = 0; si < mentionedSKUs.length; si++) {
  var sku  = mentionedSKUs[si];
  var item = null;
  for (var ri = 0; ri < inventoryRows.length; ri++) {
    if (inventoryRows[ri]['SKU'] === sku) { item = inventoryRows[ri]; break; }
  }
  if (!item) continue;

  var totalImages = parseInt(item['Total Images'] || item['totalImages'] || '1', 10) || 1;

  // Collect all available Cloudinary URLs
  var allUrls = [];
  for (var i = 1; i <= totalImages; i++) {
    var raw = item['Image ' + i + ' Direct URL']
           || item['Image' + i + ' Direct URL']
           || (i === 1 ? (item['primaryDirectUrl'] || item['Direct Image URL'] || item['Primary Image URL'] || '') : '');
    var url = toWhatsAppUrl(raw);
    if (url) allUrls.push(url);
  }
  if (allUrls.length === 0) {
    var fb = toWhatsAppUrl(item['primaryDirectUrl'] || item['Direct Image URL'] || item['Primary Image URL'] || '');
    if (fb) allUrls.push(fb);
  }
  if (allUrls.length === 0) continue;

  var itemTitle = item['AI Title'] || item['aiTitle'] || item['Item Name'] || sku;

  if (wantMoreImages && !isMultiItem) {
    // Customer asked for more photos of this single item — send ALL
    for (var j = 0; j < allUrls.length; j++) {
      imagesToSend.push({
        waFrom:      skuData.waFrom,
        imageUrl:    allUrls[j],
        sku:         sku,
        imageIndex:  j + 1,
        totalImages: allUrls.length,
        caption:     '\ud83d\udcf8 ' + itemTitle + ' \u2014 Photo ' + (j + 1) + ' of ' + allUrls.length
      });
    }
  } else {
    // First mention OR multi-item listing — always send exactly 1 photo per item
    var itemNum = si + 1;
    var numPrefix = isMultiItem ? (itemNum + '. ') : '';
    var hasMore   = allUrls.length > 1;
    var caption   = (isMultiItem ? '\ud83d\udd36 Item ' + itemNum + ': ' : '\u2728 ')
      + '*' + itemTitle + '*\n\n'
      + '\ud83d\udc8e ' + (item['Gold Carat'] || '') + ' | ' + (item['Diamond Purity'] || '') + '\n'
      + '\u2696\ufe0f ' + (item['Weight (g)'] || '') + 'g  |  \ud83d\udcb0 \u20b9' + (item['Price (INR)'] || '')
      + (!isMultiItem && hasMore ? '\n\n\ud83d\udcf8 Photo 1 of ' + allUrls.length + ' \u2014 Reply *yes* to see all!' : '');

    imagesToSend.push({
      waFrom:      skuData.waFrom,
      imageUrl:    allUrls[0],
      sku:         sku,
      imageIndex:  1,
      totalImages: allUrls.length,
      caption:     caption
    });
  }
}

var interestedItemsDetails = inventoryRows.filter(function(r) {
  return interestedSKUs.indexOf(r['SKU']) !== -1;
});

return [{
  json: {
    waFrom:                 skuData.waFrom,
    waName:                 skuData.waName,
    waMessage:              skuData.waMessage,
    aiReply:                skuData.aiReply,
    isInterested:           skuData.isInterested,
    interestedSKUs:         interestedSKUs,
    interestedItemsDetails: interestedItemsDetails,
    imagesToSend:           imagesToSend,
    _debug: {
      mentionedSKUs:     mentionedSKUs,
      isMultiItem:       isMultiItem,
      wantMoreImages:    wantMoreImages,
      inventoryRows:     inventoryRows.length,
      imagesStagedCount: imagesToSend.length,
      firstImageUrl:     imagesToSend.length > 0 ? imagesToSend[0].imageUrl : 'none'
    }
  }
}];

// No SKUs found — this is a text-only reply (greeting, general question, etc.)
// Just pass through the AI reply with empty image/interest arrays.
const d = $input.first().json;
return [{
  json: {
    waFrom:               d.waFrom,
    waName:               d.waName,
    waMessage:            d.waMessage,
    aiReply:              d.aiReply,
    isInterested:         d.isInterested,
    interestedSKUs:       d.interestedSKUs,
    interestedItemsDetails: [],
    imagesToSend:         []
  }
}];

var storeStaticData = $getWorkflowStaticData('global');
var storeName   = storeStaticData.storeName   || 'Our Store';
var ownerEmail  = storeStaticData.ownerEmail  || 'support@nelishkaai.in';
var ownerId     = storeStaticData.ownerId     || '';

var data         = $input.first().json;
var interestedSKUs = data.interestedSKUs || [];
var now          = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

// ── Recover full inventory rows to get item details ───────────────────────
// Try 1: interestedItemsDetails already populated (when SKUs path ran)
var items = data.interestedItemsDetails || [];

// Try 2: read from static data cache (always populated by Save & Compress)
if (items.length === 0 && interestedSKUs.length > 0) {
  try {
    var store = $getWorkflowStaticData('global');
    var cachedRows = store.inventoryRowsCache || [];
    items = cachedRows.filter(function(r) {
      return interestedSKUs.indexOf(r['SKU']) !== -1;
    });
  } catch(e) {}
}

// Try 3: read from Fetch Inventory from Sheets if it ran this execution
if (items.length === 0 && interestedSKUs.length > 0) {
  try {
    var fetchedRows = $('Fetch SKU Details').all().map(function(r) { return r.json; });
    items = fetchedRows.filter(function(r) {
      return interestedSKUs.indexOf(r['SKU']) !== -1;
    });
  } catch(e) {}
}

// Try 4: read from Fetch Fresh from Sheets if it ran this execution
if (items.length === 0 && interestedSKUs.length > 0) {
  try {
    var freshRows = $('Fetch Owner & Products').all().map(function(r) { return r.json; });
    items = freshRows.filter(function(r) {
      return interestedSKUs.indexOf(r['SKU']) !== -1;
    });
  } catch(e) {}
}

// ── WhatsApp message to owner ─────────────────────────────────────────────
var waLines = '';
if (items.length > 0) {
  var lineArr = [];
  for (var wi = 0; wi < items.length; wi++) {
    var it = items[wi];
    lineArr.push(
      '\uD83D\uDC8E *' + (it['AI Title'] || it['aiTitle'] || it['Item Name'] || '') + '*\n'
      + '\uD83C\uDFF7\uFE0F SKU: ' + (it['SKU'] || '') + '\n'
      + '\uD83E\uDD47 ' + (it['Gold Carat'] || '') + ' | ' + (it['Diamond Purity'] || '') + '\n'
      + '\u2696\uFE0F ' + (it['Weight (g)'] || '') + 'g | \uD83D\uDCB0 \u20B9' + (it['Price (INR)'] || '') + '\n'
      + '\uD83D\uDCE6 Stock: ' + (it['Stock Qty'] || '')
    );
  }
  waLines = lineArr.join('\n\n');
} else {
  waLines = 'SKUs: ' + interestedSKUs.join(', ');
}

var whatsappMsg =
  '\uD83D\uDD14 *New Customer Interest!* \uD83D\uDD14\n\n'
  + '\uD83D\uDC64 *Name:* ' + (data.waName || '') + '\n'
  + '\uD83D\uDCF1 *WhatsApp:* +' + (data.waFrom || '') + '\n'
  + '\uD83D\uDD50 *Time:* ' + now + '\n\n'
  + '*Interested Items:*\n\n'
  + waLines
  + '\n\nPlease contact the customer soon! \u2728';

// ── Build Cloudinary image gallery ────────────────────────────────────────
function toEmailThumb(url) {
  if (!url) return '';
  if (url.indexOf('res.cloudinary.com') === -1) return url;
  // Insert Cloudinary transformation after /upload/
  // e.g. .../upload/v123/file.jpg -> .../upload/f_jpg,q_auto,w_200,h_200,c_fill/v123/file.jpg
  var uploadMarker = '/upload/';
  var idx = url.indexOf(uploadMarker);
  if (idx === -1) return url;
  return url.slice(0, idx + uploadMarker.length)
       + 'f_jpg,q_auto,w_200,h_200,c_fill/'
       + url.slice(idx + uploadMarker.length);
}

function buildImageGallery(item) {
  var total = parseInt(item['Total Images'] || item['totalImages'] || '1', 10) || 1;
  var html  = '';
  for (var gi = 1; gi <= total; gi++) {
    var raw = item['Image ' + gi + ' Direct URL'] || '';
    if (!raw && gi === 1) {
      raw = item['primaryDirectUrl'] || item['Direct Image URL'] || item['Primary Image URL'] || '';
    }
    if (!raw) continue;
    var thumb = toEmailThumb(raw);
    html += '<div style="display:inline-block;margin:6px;text-align:center;vertical-align:top;">'
          + '<img src="' + thumb + '" width="150" height="150" '
          + 'style="display:block;object-fit:cover;border-radius:4px;border:1px solid #e8d5a3;"/>'
          + '<p style="font-size:11px;color:#999;margin:4px 0 0;">Photo ' + gi + '</p>'
          + '</div>';
  }
  return html || '<p style="color:#aaa;font-size:13px;margin:0;">No images available</p>';
}

// ── Build email ───────────────────────────────────────────────────────────
var itemNameStr  = '';
var itemsHtmlStr = '';
for (var ei = 0; ei < items.length; ei++) {
  var item  = items[ei];
  var title = item['AI Title'] || item['aiTitle'] || item['Item Name'] || '';
  if (ei > 0) itemNameStr += ', ';
  itemNameStr += title;
  itemsHtmlStr +=
    '<div style="background:white;padding:24px;border:1px solid #e8d5a3;border-top:none;">'
    + '<h2 style="color:#b8860b;font-size:18px;margin-top:0;border-bottom:2px solid #ffd700;padding-bottom:8px;">' + title + '</h2>'
    + '<table style="width:100%;border-collapse:collapse;margin-bottom:16px;">'
    + '<tr><td style="padding:5px 0;color:#888;width:140px;font-size:13px;">SKU</td>'
    + '<td style="font-family:monospace;background:#f5f5f5;padding:3px 8px;border-radius:4px;font-size:13px;">' + (item['SKU'] || '') + '</td></tr>'
    + '<tr><td style="padding:5px 0;color:#888;font-size:13px;">Gold</td><td style="font-size:13px;">' + (item['Gold Carat'] || '') + '</td></tr>'
    + '<tr><td style="padding:5px 0;color:#888;font-size:13px;">Diamond</td><td style="font-size:13px;">' + (item['Diamond Purity'] || '') + '</td></tr>'
    + '<tr><td style="padding:5px 0;color:#888;font-size:13px;">Weight</td><td style="font-size:13px;">' + (item['Weight (g)'] || '') + 'g</td></tr>'
    + '<tr><td style="padding:5px 0;color:#888;font-size:13px;">Price</td>'
    + '<td style="font-weight:bold;color:#b8860b;font-size:16px;">\u20B9' + (item['Price (INR)'] || '') + '</td></tr>'
    + '<tr><td style="padding:5px 0;color:#888;font-size:13px;">Occasions</td><td style="font-size:13px;">' + (item['Occasions'] || item['aiOccasions'] || '') + '</td></tr>'
    + '<tr><td style="padding:5px 0;color:#888;font-size:13px;">Stock</td><td style="font-size:13px;">' + (item['Stock Qty'] || '') + '</td></tr>'
    + '</table>'
    + '<p style="color:#555;font-size:14px;margin-bottom:16px;">' + (item['WhatsApp Summary'] || item['aiWhatsappSummary'] || '') + '</p>'
    + '<p style="color:#888;font-size:12px;font-weight:500;margin-bottom:8px;">\uD83D\uDCF8 Product Images</p>'
    + '<div style="margin-bottom:8px;">' + buildImageGallery(item) + '</div>'
    + '</div>';
}

if (!itemsHtmlStr) {
  itemsHtmlStr = '<div style="padding:24px;border:1px solid #e8d5a3;border-top:none;">'
    + '<p style="font-size:13px;">SKUs of interest: ' + interestedSKUs.join(', ') + '</p>'
    + '<p style="font-size:12px;color:#aaa;margin-top:8px;">Item details not available — please check inventory for SKU details.</p>'
    + '</div>';
}

var emailSubject = '\uD83D\uDC8E New Interest: ' + (data.waName || '') + ' \u2014 ' + (itemNameStr || interestedSKUs.join(', '));

var emailBody =
  '<div style="font-family:Georgia,serif;max-width:620px;margin:0 auto;color:#333;">'
  + '<div style="background:linear-gradient(135deg,#b8860b,#ffd700);padding:24px;border-radius:8px 8px 0 0;">'
  + '<h1 style="color:white;margin:0;font-size:22px;">\uD83D\uDC8E New Customer Interest</h1>'
  + '<p style="color:rgba(255,255,255,0.9);margin:8px 0 0;font-size:13px;">A customer wants to buy from your store!</p>'
  + '</div>'
  + '<div style="background:#fffdf5;padding:24px;border:1px solid #e8d5a3;border-top:none;">'
  + '<h2 style="color:#b8860b;font-size:15px;margin-top:0;">\uD83D\uDC64 Customer Details</h2>'
  + '<table style="width:100%;border-collapse:collapse;">'
  + '<tr><td style="padding:6px 0;color:#666;font-size:13px;">Name</td><td style="font-weight:bold;font-size:13px;">' + (data.waName || '') + '</td></tr>'
  + '<tr><td style="padding:6px 0;color:#666;font-size:13px;">WhatsApp</td><td style="font-weight:bold;font-size:13px;">+' + (data.waFrom || '') + '</td></tr>'
  + '<tr><td style="padding:6px 0;color:#666;font-size:13px;">Time</td><td style="font-size:13px;">' + now + '</td></tr>'
  + '</table></div>'
  + itemsHtmlStr
  + '<div style="background:#f9f4e8;padding:14px 24px;border:1px solid #e8d5a3;border-top:none;border-radius:0 0 8px 8px;font-size:12px;color:#999;">'
  + 'Sent by Aanya \u2014 AI Assistant &bull; ' + now
  + '</div></div>';

var result = {};
for (var k in data) { if (Object.prototype.hasOwnProperty.call(data, k)) result[k] = data[k]; }
result.whatsappMsg  = whatsappMsg;
result.emailSubject = emailSubject;
result.emailBody    = emailBody;
result.ownerEmail   = ownerEmail;
result.storeName    = storeName;
return [{ json: result }];

