// Token Usage Logger v10
// Fix: ownerId was ('global').ownerId in v9 — always undefined
var agentOut  = $input.first().json;
var prevData  = $('Parse WhatsApp Message').first().json;
var now       = new Date().toISOString();
var nowIST    = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

var staticStore = $getWorkflowStaticData('global');
var ownerId     = staticStore.ownerId || '';

var promptTokens = 0, completionTokens = 0, totalTokens = 0, toolCallCount = 0;

if (agentOut.tokenUsage) {
  promptTokens     = agentOut.tokenUsage.promptTokens     || agentOut.tokenUsage.input_tokens  || 0;
  completionTokens = agentOut.tokenUsage.completionTokens || agentOut.tokenUsage.output_tokens || 0;
  totalTokens      = agentOut.tokenUsage.totalTokens      || agentOut.tokenUsage.total_tokens  || 0;
}
if (!totalTokens && agentOut.usageMetadata) {
  promptTokens     = agentOut.usageMetadata.promptTokenCount     || agentOut.usageMetadata.input_tokens  || 0;
  completionTokens = agentOut.usageMetadata.candidatesTokenCount || agentOut.usageMetadata.output_tokens || 0;
  totalTokens      = agentOut.usageMetadata.totalTokenCount      || (promptTokens + completionTokens);
}
var steps = agentOut.intermediateSteps || [];
toolCallCount = steps.length;
if (!totalTokens && steps.length > 0) {
  for (var si = 0; si < steps.length; si++) {
    var u = (steps[si].action && steps[si].action.tokenUsage) || {};
    promptTokens += u.promptTokens || 0;
    completionTokens += u.completionTokens || 0;
    totalTokens += u.totalTokens || 0;
  }
}
if (!totalTokens) {
  var lastStep = steps[steps.length - 1];
  if (lastStep && lastStep.observation) {
    try {
      var obs = JSON.parse(lastStep.observation);
      if (obs.usage) {
        promptTokens     = obs.usage.prompt_tokens     || obs.usage.input_tokens  || 0;
        completionTokens = obs.usage.completion_tokens || obs.usage.output_tokens || 0;
        totalTokens      = obs.usage.total_tokens      || (promptTokens + completionTokens);
      }
    } catch(e) {}
  }
}

var dataSource = 'actual';
if (!totalTokens) {
  completionTokens = Math.ceil(String(agentOut.output || '').length / 4);
  totalTokens      = completionTokens;
  dataSource       = 'estimated';
}

var costUSD = ((promptTokens * 0.59) + (completionTokens * 0.79)) / 1000000;
var costINR = costUSD * 84;

return [{ json: {
  ownerId,
  agentOutput: agentOut, agentOutputText: String(agentOut.output || ''),
  waFrom: prevData.waFrom || '', waName: prevData.waName || '', waMessage: prevData.waMessage || '',
  timestampIST: nowIST, timestampISO: now,
  promptTokens, completionTokens, totalTokens, toolCallCount,
  costUSD: parseFloat(costUSD.toFixed(6)), costINR: parseFloat(costINR.toFixed(4)),
  dataSource, replyLength: String(agentOut.output || '').length
}}];

// Pass the original agent output forward to Extract SKUs
// agentOutput is the full agent object; output is the text reply
var d = $input.first().json;
var out = d.agentOutput || {};

// If output text has JSON-escaped newlines, restore them here
// This happens when the agent output passes through JSON serialisation
if (out.output && typeof out.output === 'string') {
  out = JSON.parse(JSON.stringify(out));
  out.output = out.output.replace(/\\n/g, '\n').replace(/\\t/g, '\t');
}

return [{ json: out }];

const CACHE_TTL_MS = 30 * 60 * 1000; // 30 min
const waData = $input.first().json;
const waMsg  = (waData.waMessage || '').trim();

// Image/audio messages must always bypass greeting check and force fresh inventory
const isImageOrAudio = (waData.messageType === 'image' || waData.messageType === 'audio'
  || waMsg.startsWith('PHOTO_ANALYSIS'));

const isGreeting = !isImageOrAudio && (/^(hi+|hello+|hey+|namaste|namaskar|hii+|helo|hy|good\s*(morning|afternoon|evening|night)|howdy|hai|hlo|hlw|hye)[\s!.]*$/i.test(waMsg)
  || /^(\u0928\u092e\u0938\u094d\u0924\u0947|\u0928\u092e\u0938\u094d\u0915\u093e\u0930|\u0939\u0947\u0932\u094b|\u0939\u0940)[\s!.]*$/i.test(waMsg));

// ── CATEGORY DETECTION ─────────────────────────────────────────────────
// Maps keywords (English + Hinglish + Hindi romanized) to DB category values
var categoryMap = [
  { cat: 'Ring',      words: ['ring','rings','anguthi','anghuthi','angoothi','ungli','ring chahiye','ring dikhao'] },
  { cat: 'Bangle',    words: ['bangle','bangles','bangle chahiye','bangles dikhao','kada','kangan','chudi','churi','choodi','bangdi','valayu'] },
  { cat: 'Bracelet',  words: ['bracelet','bracelets','bracelet chahiye','haath ka','wristband'] },
  { cat: 'Necklace',  words: ['necklace','necklaces','haar','mala','kanthi','gala','gulband','necklace chahiye'] },
  { cat: 'Earring',   words: ['earring','earrings','ear ring','ear rings','bali','tops','jhumka','jhumki','jhoomka','kaan','earing','earings','studs'] },
  { cat: 'Pendant',   words: ['pendant','pendants','locket','latkan','pendant chahiye'] },
  { cat: 'Chain',     words: ['chain','chains','chain chahiye','gold chain','zanjeer'] },
  { cat: 'Maangtika', words: ['maangtika','maang tikka','maang tika','tikka','matha patti','mathapatti'] },
  { cat: 'Nosering',  words: ['nosering','nose ring','nath','nathni','laung','naak'] },
  { cat: 'Anklet',    words: ['anklet','anklets','payal','pajeb','payjeb','paizeb'] },
  { cat: 'Set',       words: ['set','jewellery set','jewelry set','bridal set','wedding set','full set'] }
];

var detectedCategory = '';

// For image messages — category comes from Build Message from Image imageCategory field
if (isImageOrAudio && waData.imageCategory) {
  var ic = waData.imageCategory.toLowerCase().trim();
  for (var ci = 0; ci < categoryMap.length; ci++) {
    if (ic === categoryMap[ci].cat.toLowerCase() || categoryMap[ci].words.indexOf(ic) !== -1) {
      detectedCategory = categoryMap[ci].cat;
      break;
    }
  }
  // If no exact match, use the raw imageCategory as-is (capitalised)
  if (!detectedCategory && ic) {
    detectedCategory = ic.charAt(0).toUpperCase() + ic.slice(1);
  }
}

// For text/hinglish messages — scan waMsg for category keywords
if (!detectedCategory && !isImageOrAudio && waMsg) {
  var msgLower = waMsg.toLowerCase();
  outer:
  for (var mi = 0; mi < categoryMap.length; mi++) {
    var words = categoryMap[mi].words;
    for (var wi = 0; wi < words.length; wi++) {
      if (msgLower.indexOf(words[wi]) !== -1) {
        detectedCategory = categoryMap[mi].cat;
        break outer;
      }
    }
  }
}

const store    = $getWorkflowStaticData('global');
const cached   = store.inventoryText    || '';
const cachedAt = store.inventoryCachedAt || 0;
const nowMs    = Date.now();

// Normalize detectedCategory to match exact Supabase values
// Image Explainer may return 'ring/set', 'ring', 'bangle', etc. — must match DB exactly
var categoryNormalizeMap = {
  'ring': 'Ring', 'rings': 'Ring', 'ring/set': 'Ring',
  'bangle': 'Bangle', 'bangles': 'Bangle', 'bangle/bracelet': 'Bangle',
  'bracelet': 'Bracelet', 'bracelets': 'Bracelet',
  'necklace': 'Necklace', 'necklaces': 'Necklace', 'necklace/set': 'Necklace',
  'earring': 'Earring', 'earrings': 'Earring', 'ear ring': 'Earring',
  'pendant': 'Pendant', 'pendants': 'Pendant', 'pendant/chain': 'Pendant',
  'chain': 'Chain', 'chains': 'Chain',
  'set': 'Set', 'jewellery set': 'Set', 'jewelry set': 'Set',
  'maangtika': 'Maangtika', 'maang tikka': 'Maangtika',
  'nosering': 'Nosering', 'nose ring': 'Nosering', 'nath': 'Nosering',
  'anklet': 'Anklet', 'anklets': 'Anklet', 'payal': 'Anklet'
};

if (detectedCategory) {
  var rawLower = detectedCategory.toLowerCase().trim();
  // Try exact map first
  if (categoryNormalizeMap[rawLower]) {
    detectedCategory = categoryNormalizeMap[rawLower];
  } else {
    // Try prefix match — e.g. 'ring/set' -> check if starts with any key
    var matched = false;
    var mapKeys = Object.keys(categoryNormalizeMap);
    for (var ni = 0; ni < mapKeys.length; ni++) {
      if (rawLower.indexOf(mapKeys[ni]) === 0 || rawLower.indexOf(mapKeys[ni]) !== -1) {
        detectedCategory = categoryNormalizeMap[mapKeys[ni]];
        matched = true;
        break;
      }
    }
    // If still no match, capitalize first letter as fallback
    if (!matched) {
      detectedCategory = detectedCategory.charAt(0).toUpperCase() + detectedCategory.slice(1).toLowerCase();
    }
  }
}

// Cache is only valid if same category (or no category = full inventory)
const cachedCategory = store.inventoryCachedCategory || '';
const categoryMatches = (detectedCategory === cachedCategory);
const isValid = !isImageOrAudio && cached && categoryMatches && (nowMs - cachedAt) < CACHE_TTL_MS;

return [{ json: {
  waFrom:            waData.waFrom,
  waName:            waData.waName,
  waMessage:         waMsg,
  messageType:       waData.messageType || 'text',
  imageCategory:     waData.imageCategory || '',
  isGreeting:        isGreeting,
  useCache:          isGreeting || isValid,
  cachedText:        cached,
  cacheAgeMin:       Math.round((nowMs - cachedAt) / 60000),
  detectedCategory:  detectedCategory
}}];

const d = $input.first().json;
const store = $getWorkflowStaticData('global');
return [{ json: {
  waFrom:        d.waFrom,
  waName:        d.waName,
  waMessage:     d.waMessage,
  inventoryText: d.isGreeting ? '' : d.cachedText,
  ownerId:       store.ownerId    || '',
  storeName:     store.storeName  || 'Our Store',
  ownerEmail:    store.ownerEmail || '',
  cacheHit:      d.isGreeting ? 'greeting_skip' : 'cache_hit',
  cacheAgeMin:   d.cacheAgeMin
}}];

// Save & Compress Inventory v10
// Input 0: store row from Fetch Owner & Products (owner_id, store_name, email)
// Input from Fetch Products by Owner: array of product rows
var storeItem  = $('Fetch Owner & Products').first().json;
// waMessage must come from Check Cache (has PHOTO_ANALYSIS / original message)
// NOT from Fetch Owner & Products (store row has no waMessage)
var waData     = $('Check Cache').first().json;
var ownerId    = storeItem.owner_id   || '';
var storeName  = storeItem.store_name || 'Our Store';
var ownerEmail = storeItem.email      || '';

if (!ownerId) {
  return [{ json: {
    waFrom: waData.waFrom, waName: waData.waName, waMessage: waData.waMessage,
    inventoryText: '', ownerId: '', storeName: 'Unknown',
    cacheHit: 'no_store_found', cacheAgeMin: 0
  }}];
}

// Products come from Fetch Products by Owner HTTP node
// n8n HTTP node returns array items — collect all items
var allItems = $input.all();
var products = allItems.map(function(item) { return item.json; });

var rows = products.map(function(p) {
  var images = Array.isArray(p.images) ? p.images : [];
  var row = {
    'SKU':               p.sku              || '',
    'Item Name':         p.name             || '',
    'AI Title':          p.name || '',
    'Category':          p.category         || '',
    'Gold Carat':        p.gold_carat       || '',
    'Diamond Purity':    p.diamond_purity   || 'N/A',
    'Weight (g)':        String(p.weight    || ''),
    'Price (INR)':       String(p.price     || ''),
    'Stock Qty':         String(p.stock_qty || '1'),
    'Occasions':         p.occasion || '',
    'WhatsApp Summary':  (p.description || '').slice(0, 140),
    'Status':            'Active',
    'Total Images':      String(images.length || 1),
    'Primary Image URL': p.primary_image_url || (images[0] || '')
  };
  for (var i = 0; i < Math.min(images.length, 5); i++) {
    row['Image ' + (i+1) + ' Direct URL'] = images[i] || '';
  }
  return row;
});

var lines = rows.map(function(r) {
  return 'SKU:' + r['SKU'] + '|'
       + (r['AI Title'] || r['Item Name']) + '|'
       + 'Cat:' + r['Category'] + '|'
       + r['Gold Carat'] + '|'
       + (r['Diamond Purity'] || 'N/A') + '|'
       + r['Weight (g)'] + 'g|'
       + 'Rs.' + r['Price (INR)'] + '|'
       + 'Qty:' + r['Stock Qty'] + '|'
       + r['Occasions'] + '|'
       + 'Photos:' + r['Total Images'];
});

var inventoryText = rows.length > 0
  ? 'INVENTORY (' + rows.length + ' items' + (waData.detectedCategory ? ' [Category: ' + waData.detectedCategory + ']' : '') + '):\n' + lines.join('\n')
  : 'INVENTORY (0 items' + (waData.detectedCategory ? ' [Category: ' + waData.detectedCategory + ']' : '') + '): No products in this category currently in stock.';

var staticData = $getWorkflowStaticData('global');
staticData.inventoryText          = inventoryText;
staticData.inventoryCachedAt      = Date.now();
staticData.inventoryRowsCache     = rows;
staticData.inventoryCachedCategory = waData.detectedCategory || '';
staticData.ownerId                = ownerId;
staticData.storeName              = storeName;
staticData.ownerEmail             = ownerEmail;

return [{ json: {
  waFrom:        waData.waFrom,
  waName:        waData.waName,
  waMessage:     waData.waMessage,
  inventoryText: inventoryText,
  ownerId:       ownerId,
  storeName:     storeName,
  ownerEmail:    ownerEmail,
  cacheHit:      'miss_refreshed',
  cacheAgeMin:   0
}}];

