const transcription = $input.first().json;
const prevData = $('Parse WhatsApp Message').first().json;

var transcribedText = transcription.text
  || (transcription.results && transcription.results.text)
  || '';

var detectedLang = transcription.language
  || (transcription.results && transcription.results.language)
  || '';

var langMap = {
  'hi': 'Hindi', 'mr': 'Marathi', 'gu': 'Gujarati',
  'bn': 'Bengali', 'ta': 'Tamil',  'te': 'Telugu',
  'kn': 'Kannada', 'ml': 'Malayalam', 'pa': 'Punjabi',
  'ur': 'Urdu',   'en': 'English', 'or': 'Odia'
};
var langName = langMap[detectedLang] || detectedLang || 'Hindi';

if (!transcribedText) {
  return [{ json: {
    waFrom:       prevData.waFrom,
    waName:       prevData.waName,
    waMessage:    'Customer sent a voice message that could not be transcribed. Please ask them to type their message.',
    messageType:  'audio_failed',
    originalType: 'audio',
    detectedLang: detectedLang,
    mediaId:      prevData.mediaId
  }}];
}

// Prefix with language instruction so AI replies in correct language
var waMessage = '[AUDIO MESSAGE - spoken in ' + langName + ', reply in ' + langName + ']\n' + transcribedText;

return [{ json: {
  waFrom:       prevData.waFrom,
  waName:       prevData.waName,
  waMessage:    waMessage,
  messageType:  'audio_transcribed',
  originalType: 'audio',
  detectedLang: detectedLang,
  langName:     langName,
  mediaId:      prevData.mediaId
}}];

const data     = $input.first().json;
const prevData = $('Parse WhatsApp Message').first().json;

var description = data.text || data.response || data.output || '';

// Parse structured fields from Image Explainer output
function extractField(text, field) {
  var regex = new RegExp(field + ':\\s*(.+)', 'i');
  var match = text.match(regex);
  return match ? match[1].trim() : '';
}

var category    = extractField(description, 'CATEGORY');
var metalColor  = extractField(description, 'METAL_COLOR');
var goldCarat   = extractField(description, 'GOLD_CARAT');
var style       = extractField(description, 'STYLE');
var stones      = extractField(description, 'STONES');
var designDesc  = extractField(description, 'DESIGN_DETAILS');

// Build a precise search query for AI Agent
var searchQuery = '';

if (description && description.length > 10) {
  searchQuery = 'PHOTO_ANALYSIS:\n'
    + 'Category: ' + (category || 'unknown') + '\n'
    + 'Metal: ' + (metalColor || 'unknown') + '\n'
    + 'Gold Carat: ' + (goldCarat || 'unknown') + '\n'
    + 'Style: ' + (style || 'unknown') + '\n'
    + 'Stones: ' + (stones || 'none') + '\n'
    + 'Design: ' + (designDesc || 'not specified') + '\n\n'
    + 'MATCHING INSTRUCTIONS:\n'
    + '1. Search inventory for items where Cat matches "' + (category || '') + '".\n'
    + '2. From those, find items where Gold Carat contains "' + (goldCarat || '') + '" OR metal color matches.\n'
    + '3. EXACT MATCH = same category + same style + same metal. If found, show it with [SKU: XXXX].\n'
    + '4. CLOSE MATCH = same category + similar metal. If found, show with [SKU: XXXX] and note the difference.\n'
    + '5. NO MATCH = if NO item in inventory matches even the category, say so honestly.\n'
    + '6. NEVER suggest an item from a different category (e.g. do not suggest a ring for a necklace photo).\n'
    + '7. Start reply by briefly describing the photo to the customer in 1 warm sentence.\n'
    + '8. Reply in the same language/script the customer has been using.';
} else {
  searchQuery = 'Customer uploaded a photo but it could not be analyzed clearly. Please ask them to describe what they are looking for.';
}

return [{ json: {
  waFrom:           prevData.waFrom,
  waName:           prevData.waName,
  waMessage:        searchQuery,
  messageType:      'image_search',
  originalType:     'image',
  imageDescription: description,
  imageCategory:    category,
  imageStyle:       style,
  imageMetalColor:  metalColor
}}];

// Lookup Store Owner v10
// Also fetches owner_whatsapp for alert delivery
const d          = $input.first().json;
const phoneNumId = $('WhatsApp Trigger').first().json.metadata.display_phone_number || '';
const SERVICE_KEY = ($env.SUPABASE_SERVICE_KEY || '');
const BASE_URL    = 'https://bigmdvjrvqyqzyrijdum.supabase.co';

var ownerId       = '';
var storeName     = 'Our Store';
var ownerEmail    = '';
var ownerWhatsApp = '';

try {
  var resp = await $http.get(
    BASE_URL + '/rest/v1/stores?whatsapp_phone=eq.' + encodeURIComponent(phoneNumId)
    + '&select=owner_id,store_name,email,status,owner_whatsapp&limit=1',
    { headers: {
        'apikey': SERVICE_KEY,
        'Authorization': 'Bearer ' + SERVICE_KEY
    }}
  );
  var rows = Array.isArray(resp) ? resp : (resp.data ? resp.data : []);
  var storeRow = rows.length > 0 ? rows[0] : null;
  if (storeRow) {
    ownerId       = storeRow.owner_id        || '';
    storeName     = storeRow.store_name      || 'Our Store';
    ownerEmail    = storeRow.email           || '';
    ownerWhatsApp = storeRow.owner_whatsapp  || '';
  }
} catch(e) {}

if (ownerId) {
  var store = $getWorkflowStaticData('global');
  store.ownerId       = ownerId;
  store.storeName     = storeName;
  store.ownerEmail    = ownerEmail;
  store.ownerWhatsApp = ownerWhatsApp;
}

return [{ json: Object.assign({}, d, { ownerId, storeName, ownerEmail, ownerWhatsApp }) }];

// Subscription and Usage Check v10
const d       = $input.first().json;
const ownerId = d.ownerId || '';
const waFrom  = d.waFrom  || '';
const SK      = ($env.SUPABASE_SERVICE_KEY || '');
const BASE    = 'https://bigmdvjrvqyqzyrijdum.supabase.co';

if (!ownerId) {
  return [{ json: Object.assign({}, d, {
    subscriptionOk: true, planName: 'unknown',
    conversationLimit: 9999, monthlyBudgetInr: 9999,
    conversationsUsed: 0, costUsedInr: 0,
    convPct: 0, costPct: 0, usagePct: 0, alertLevel: 'none',
    isNewSession: true, sessionId: null
  })}];
}

var sr = await $http.get(
  BASE + '/rest/v1/stores?owner_id=eq.' + ownerId
  + '&select=plan_name,conversation_limit,monthly_budget_inr,subscription_status,plan_expires_at,owner_whatsapp,email&limit=1',
  { headers: { 'apikey': SK, 'Authorization': 'Bearer ' + SK }}
);
var srows = Array.isArray(sr) ? sr : (sr.data || []);
var store = srows[0] || {};

var planName          = store.plan_name           || 'starter';
var conversationLimit = store.conversation_limit  || 500;
var monthlyBudgetInr  = store.monthly_budget_inr  || 250;
var subStatus         = store.subscription_status || 'active';
var planExpiresAt     = store.plan_expires_at     || null;
var ownerWhatsApp     = store.owner_whatsapp      || d.ownerWhatsApp || '';
var ownerEmail        = store.email               || d.ownerEmail    || '';

var isExpired = subStatus === 'expired' || subStatus === 'cancelled'
  || (planExpiresAt && new Date(planExpiresAt) < new Date());

var now      = new Date();
var monthKey = now.getFullYear() + '_' + String(now.getMonth() + 1).padStart(2, '0');

var sessionData = { session_id: null, is_new_session: true };
try {
  var sessionResp = await $http.post(
    BASE + '/rest/v1/rpc/upsert_session',
    { owner_id: ownerId, wa_from: waFrom, month_key: monthKey },
    { headers: { 'apikey': SK, 'Authorization': 'Bearer ' + SK, 'Content-Type': 'application/json' }}
  );
  var sessionRows = Array.isArray(sessionResp) ? sessionResp : (sessionResp.data || []);
  if (sessionRows[0]) sessionData = sessionRows[0];
} catch(e) {}

var isNewSession = sessionData.is_new_session !== false;
var sessionId    = sessionData.session_id || null;

var usageResp = await $http.get(
  BASE + '/rest/v1/owner_usage_current?owner_id=eq.' + ownerId,
  { headers: { 'apikey': SK, 'Authorization': 'Bearer ' + SK }}
);
var urows = Array.isArray(usageResp) ? usageResp : (usageResp.data || []);
var usage = urows[0] || {};

var conversationsUsed = parseInt(usage.conversations_used || 0);
var costUsedInr       = parseFloat(usage.cost_used_inr    || 0);

var convPct  = conversationLimit > 0 ? Math.round(conversationsUsed / conversationLimit * 100) : 0;
var costPct  = monthlyBudgetInr  > 0 ? Math.round(costUsedInr       / monthlyBudgetInr  * 100) : 0;
var usagePct = Math.max(convPct, costPct);

var limitReason = '';
if (isExpired)                                   limitReason = 'subscription_expired';
else if (conversationsUsed >= conversationLimit) limitReason = 'conversation_limit';
else if (costUsedInr >= monthlyBudgetInr)        limitReason = 'cost_limit_internal';
var subscriptionOk = limitReason === '';

var alertLevel = 'none';
if (!subscriptionOk) {
  alertLevel = 'limit_reached';
} else if (usagePct >= 90) {
  try {
    var flagResp = await $http.get(
      BASE + '/rest/v1/alert_flags?owner_id=eq.' + ownerId
           + '&alert_type=eq.90_percent&month_key=eq.' + monthKey + '&limit=1',
      { headers: { 'apikey': SK, 'Authorization': 'Bearer ' + SK }}
    );
    var frows = Array.isArray(flagResp) ? flagResp : (flagResp.data || []);
    if (frows.length === 0) alertLevel = '90_percent';
  } catch(e) {
    alertLevel = '90_percent';
  }
}

return [{ json: Object.assign({}, d, {
  subscriptionOk, limitReason, planName,
  conversationLimit, conversationsUsed, convPct,
  monthlyBudgetInr, costUsedInr: Math.round(costUsedInr * 100) / 100, costPct,
  usagePct, alertLevel, monthKey,
  isNewSession, sessionId, ownerWhatsApp, ownerEmail,
  subStatus, isExpired
}) }];

const d = $input.first().json;
const reason    = d.limitReason || 'unknown';

// Customer always gets the same polite message — no technical details
const customerMsg = 'Hello! Our automated assistant is temporarily unavailable.\n'
  + 'Please contact us directly for product enquiries. Thank you for your patience! \uD83D\uDE4F';

var ownerSubject, ownerAlert;

if (reason === 'subscription_expired') {
  ownerSubject = '⚠️ Swarnix — Subscription Expired';
  ownerAlert   = '*Swarnix Alert*\n\n'
    + 'Your subscription has *expired*. Your WhatsApp AI bot is now *offline*.\n\n'
    + 'Renew your subscription to reactivate: support@nelishkaai.in';

} else if (reason === 'cost_limit_internal') {
  // Owner-facing message: same as conversation limit — no LLM cost details
  ownerSubject = '🚫 Swarnix — Monthly Limit Reached';
  ownerAlert   = '*Swarnix: Monthly Limit Reached*\n\n'
    + 'Your WhatsApp AI bot has reached its monthly limit.\n\n'
    + '*Conversations used:* ' + d.conversationsUsed + '\n'
    + '*Plan:* ' + d.planName + '\n\n'
    + 'The bot is *paused* until 1st of next month or until you upgrade.\n\n'
    + 'Upgrade your plan: support@nelishkaai.in';

} else {
  // conversation_limit or anything else
  ownerSubject = '🚫 Swarnix — Monthly Conversation Limit Reached';
  ownerAlert   = '*Swarnix: Monthly Limit Reached*\n\n'
    + '*Conversations used:* ' + d.conversationsUsed + ' / ' + d.conversationLimit + '\n'
    + '*Plan:* ' + d.planName + '\n\n'
    + 'The bot is *paused* until 1st of next month or until you upgrade.\n\n'
    + 'Upgrade your plan: support@nelishkaai.in';
}

return [{ json: {
  waFrom: d.waFrom, ownerEmail: d.ownerEmail,
  customerMsg, ownerAlert, ownerSubject,
  planName: d.planName, usagePct: d.usagePct,
  limitReason: reason
}}];

// Check 90% Alert v10
// v10: inserts row into alert_flags table instead of n8n static data
const d = $input.first().json;

if (d.alertLevel !== '90_percent') {
  return [{ json: { sendAlert: false } }];
}

const SK   = ($env.SUPABASE_SERVICE_KEY || '');
const BASE = 'https://bigmdvjrvqyqzyrijdum.supabase.co';

try {
  await $http.post(
    BASE + '/rest/v1/alert_flags',
    { owner_id: d.ownerId, alert_type: '90_percent', month_key: d.monthKey },
    { headers: {
        'apikey': SK,
        'Authorization': 'Bearer ' + SK,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
    }}
  );
} catch(e) {
  return [{ json: { sendAlert: false } }];
}

const remaining = d.conversationLimit - d.conversationsUsed;

const line1 = '[Swarnix] Usage Alert';
const line2 = 'Plan: ' + d.planName;
const line3 = 'Conversations used: ' + d.conversationsUsed + ' / ' + d.conversationLimit + ' (' + d.convPct + '%)';
const line4 = 'Remaining: ' + remaining + ' conversations';
const line5 = 'Resets: 1st of next month';
const line6 = 'Upgrade to avoid interruption.';
const line7 = 'Contact: support@nelishkaai.in';

const ownerMsg = [line1, line2, line3, line4, line5, line6, line7].join('\n');

return [{ json: {
  sendAlert:     true,
  ownerEmail:    d.ownerEmail    || 'support@nelishkaai.in',
  ownerWhatsApp: d.ownerWhatsApp || '',
  ownerMsg,
  subject: '[Swarnix] WARNING - ' + d.convPct + '% Conversations Used - ' + d.planName,
  usagePct: d.usagePct,
  planName: d.planName
}}];
